    w.later(stepEncLcnCtlRcError, addr x.arm_lcn_Ctl_rc_error, addr dst[])
  of LcnCtlOutcomeKind.lcn_Ctl_refused:
    w.later(stepEncLcnCtlRefused, addr x.arm_lcn_Ctl_refused, addr dst[])

proc stepDecLcnCtlOutcome*(w: var DecWork, v: CborValue, dst: pointer) =
  let r = cast[ptr LcnCtlOutcome](dst)
  case generatedSchema().arm("lcn.ctl_outcome#", v)
  of 0:
    r[] = LcnCtlOutcome(kind: LcnCtlOutcomeKind.lcn_Ctl_ok)
    w.later(stepDecLcnCtlOk, v, addr r.arm_lcn_Ctl_ok)
  of 1:
    r[] = LcnCtlOutcome(kind: LcnCtlOutcomeKind.lcn_Ctl_refused)
    w.later(stepDecLcnCtlRefused, v, addr r.arm_lcn_Ctl_refused)
  of 2:
    r[] = LcnCtlOutcome(kind: LcnCtlOutcomeKind.lcn_Ctl_rc_error)
    w.later(stepDecLcnCtlRcError, v, addr r.arm_lcn_Ctl_rc_error)
  else:
    raiseAssert "a checked value selects a known arm"

proc toCbor*(x: LcnCtlOutcome): CborValue =
  runEnc(stepEncLcnCtlOutcome, addr x)

proc fromChecked*(T: type LcnCtlOutcome, v: CborValue): LcnCtlOutcome =
  var r: LcnCtlOutcome
  runDec(stepDecLcnCtlOutcome, v, addr r)
  r

proc stepEncLcnCtlRcCommand*(w: var EncWork, src: pointer, dst: ptr CborValue) =
  let x {.used.} = cast[ptr LcnCtlRcCommand](src)
  var n = 3
  if x.deadline_ms.isSome:
    inc n
  let node = CborValue(kind: ckMap, entries: newSeq[CborEntry](n))
  dst[] = node
  var k = 0
  if x.deadline_ms.isSome:
    node.entries[k].key = cbor("deadline_ms")
    node.entries[k].value = cbor(uint64(x.deadline_ms.get))
    inc k
  node.entries[k].key = cbor("method")
  w.later(stepEncLcnCtlMethod, addr x.`method`, addr node.entries[k].value)
  inc k
  node.entries[k].key = cbor("op")
  node.entries[k].value = cbor("rc")
  inc k
  node.entries[k].key = cbor("params")
  node.entries[k].value = cbor(x.params)
  inc k

proc stepDecLcnCtlRcCommand*(w: var DecWork, v: CborValue, dst: pointer) =
  let r = cast[ptr LcnCtlRcCommand](dst)
  r[] = LcnCtlRcCommand()
  let f3 = v.lookup("deadline_ms")
  if f3.isSome:
    r.deadline_ms = Opt.some(uint32(f3.get.uint))
  let f4 = v.lookup("method").get
  w.later(stepDecLcnCtlMethod, f4, addr r.`method`)
  r.params = v.lookup("params").get.bytes

proc toCbor*(x: LcnCtlRcCommand): CborValue =
  runEnc(stepEncLcnCtlRcCommand, addr x)

proc fromChecked*(T: type LcnCtlRcCommand, v: CborValue): LcnCtlRcCommand =
  var r: LcnCtlRcCommand
  runDec(stepDecLcnCtlRcCommand, v, addr r)
  r

proc stepEncLcnCtlRcError*(w: var EncWork, src: pointer, dst: ptr CborValue) =
  let x {.used.} = cast[ptr LcnCtlRcError](src)
  var n = 2
  if x.detail.isSome:
    inc n
  if x.message.isSome:
    inc n
  let node = CborValue(kind: ckMap, entries: newSeq[CborEntry](n))
  dst[] = node
  var k = 0
  node.entries[k].key = cbor("code")
  node.entries[k].value = cbor(uint64(x.code))
  inc k
  if x.detail.isSome:
    node.entries[k].key = cbor("detail")
    node.entries[k].value = cbor(x.detail.get)
    inc k
  if x.message.isSome:
    node.entries[k].key = cbor("message")
    node.entries[k].value = cbor(x.message.get)
    inc k
  node.entries[k].key = cbor("status")
  node.entries[k].value = cbor("rc-error")
  inc k

proc stepDecLcnCtlRcError*(w: var DecWork, v: CborValue, dst: pointer) =
  let r = cast[ptr LcnCtlRcError](dst)
  r[] = LcnCtlRcError()
  r.code = uint8(v.lookup("code").get.uint)
  let f5 = v.lookup("detail")
  if f5.isSome:
    r.detail = Opt.some(f5.get.bytes)
  let f6 = v.lookup("message")
  if f6.isSome:
    r.message = Opt.some(f6.get.text)

proc toCbor*(x: LcnCtlRcError): CborValue =
  runEnc(stepEncLcnCtlRcError, addr x)

proc fromChecked*(T: type LcnCtlRcError, v: CborValue): LcnCtlRcError =
  var r: LcnCtlRcError
  runDec(stepDecLcnCtlRcError, v, addr r)
  r

proc stepEncLcnCtlRefusedReasonChoice*(w: var EncWork, src: pointer, dst: ptr CborValue) =
  let x {.used.} = cast[ptr LcnCtlRefusedReasonChoice](src)
  case x.kind
  of LcnCtlRefusedReasonChoiceKind.Busy:
    dst[] = cbor("busy")
  of LcnCtlRefusedReasonChoiceKind.Closing:
    dst[] = cbor("closing")
  of LcnCtlRefusedReasonChoiceKind.Command:
    dst[] = cbor("command")
  of LcnCtlRefusedReasonChoiceKind.Protocol:
    dst[] = cbor("protocol")
  of LcnCtlRefusedReasonChoiceKind.Too_large:
    dst[] = cbor("too-large")

proc stepDecLcnCtlRefusedReasonChoice*(w: var DecWork, v: CborValue, dst: pointer) =
  let r = cast[ptr LcnCtlRefusedReasonChoice](dst)
  case generatedSchema().arm("lcn.ctl_refused#reason", v)
  of 0:
    r[] = LcnCtlRefusedReasonChoice(kind: LcnCtlRefusedReasonChoiceKind.Busy)
  of 1:
    r[] = LcnCtlRefusedReasonChoice(kind: LcnCtlRefusedReasonChoiceKind.Closing)
  of 2:
    r[] = LcnCtlRefusedReasonChoice(kind: LcnCtlRefusedReasonChoiceKind.Command)
  of 3:
    r[] = LcnCtlRefusedReasonChoice(kind: LcnCtlRefusedReasonChoiceKind.Protocol)
  of 4:
    r[] = LcnCtlRefusedReasonChoice(kind: LcnCtlRefusedReasonChoiceKind.Too_large)
  else:
    raiseAssert "a checked value selects a known arm"

proc toCbor*(x: LcnCtlRefusedReasonChoice): CborValue =
