proc stepEncLcnCtlReply*(w: var EncWork, src: pointer, dst: ptr CborValue) =
  let x {.used.} = cast[ptr LcnCtlReply](src)
  let node = CborValue(kind: ckMap, entries: newSeq[CborEntry](3))
  dst[] = node
  var k = 0
  node.entries[k].key = cbor("deployment")
  w.later(stepEncLcnCtlDeployment, addr x.deployment, addr node.entries[k].value)
  inc k
  node.entries[k].key = cbor("outcome")
  w.later(stepEncLcnCtlOutcome, addr x.outcome, addr node.entries[k].value)
  inc k
  node.entries[k].key = cbor("protocol")
  node.entries[k].value = cbor("logos-core-nim.ctl.v1")
  inc k

proc stepDecLcnCtlReply*(w: var DecWork, v: CborValue, dst: pointer) =
  let r = cast[ptr LcnCtlReply](dst)
  r[] = LcnCtlReply()
  let f9 = v.lookup("deployment").get
  w.later(stepDecLcnCtlDeployment, f9, addr r.deployment)
  let f10 = v.lookup("outcome").get
  w.later(stepDecLcnCtlOutcome, f10, addr r.outcome)

